-- Theme: monochrome dark (Claude dark-mode grays); Catppuccin Mocha only for highlighted text
local theme = {
    base     = "262624", -- Claude dark bg-100
    surface  = "30302e", -- Claude dark bg-000
    raised   = "4a4a47", -- selected / active surfaces
    border   = "e6e6e6", -- light gray, active window border
    text     = "faf9f5", -- Claude dark text-100
}

-- Refer to https://wiki.hypr.land/configuring/core/config-options/
hl.config({
    general = {
        gaps_in  = 4,
        gaps_out = 8,

        border_size = 3,

        col = {
            active_border   = "rgb(" .. theme.border .. ")",
            inactive_border = "rgb(" .. theme.surface .. ")",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/configuring/extra/tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 0,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        -- Darken unfocused windows so the active one stands out
        dim_inactive = true,
        dim_strength = 0.2,

        shadow = {
            enabled      = false,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        blur = {
            enabled   = true,
            size      = 3,
            passes    = 1,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },

    group = {
        col = {
            border_active          = "rgb(" .. theme.border .. ")",
            border_inactive        = "rgb(" .. theme.surface .. ")",
            border_locked_active   = "rgb(" .. theme.border .. ")",
            border_locked_inactive = "rgb(" .. theme.surface .. ")",
        },
        groupbar = {
            font_family = "Pretendard",
            text_color = "rgb(" .. theme.text .. ")",
            col = {
                active          = "rgb(" .. theme.raised .. ")",
                inactive        = "rgb(" .. theme.surface .. ")",
                locked_active   = "rgb(" .. theme.raised .. ")",
                locked_inactive = "rgb(" .. theme.surface .. ")",
            },
